import React, { useState } from 'react';
import {
  Clock,
  CheckCircle2,
  AlertTriangle,
  Info,
  Train,
  ArrowRight,
  ShieldCheck,
  Lock,
  Sparkles,
  Zap,
  Layers,
  ChevronDown,
  ChevronUp,
  Ticket,
  ExternalLink,
  MapPin,
  Calendar,
  RefreshCw,
  Loader2,
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { clsx } from 'clsx';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { getTrainSupportedClasses, getDefaultActiveClass } from '../../utils/trainClasses';
import { isPaidOrAdminUser } from '../../lib/rescueEntitlement';
import { VerticalStationTimeline } from './VerticalStationTimeline';
import { TripBoardingPassModal } from './TripBoardingPassModal';
import { getStationDetails, formatTextWithStations } from '../../utils/stationNames';
import { parseRailwayAvailability } from '../../utils/railwayAvailability';
import { classifyAvailability } from '../../utils/availabilityClassifier';
import { BorderBeam } from '../ui/BorderBeam';

// Clean train number formatting
const cleanTrainNo = (no: any) => {
  if (!no) return '';
  const s = String(no).trim();
  if (/^\d+$/.test(s)) return s.padStart(5, '0');
  return s;
};

// Safe layover thresholds aligned with Indian Railways operations
function getBufferMeta(bufferMins: number) {
  if (bufferMins >= 120) {
    return {
      label: 'Safe Connection',
      color: 'success',
      bar: 'bg-emerald-500',
      text: 'text-emerald-600 dark:text-emerald-400',
      border: 'border-emerald-500/30',
      bg: 'bg-emerald-500/10',
      glow: 'shadow-emerald-500/15',
    };
  }
  if (bufferMins >= 60) {
    return {
      label: 'Moderate: Delay Risk',
      color: 'warning',
      bar: 'bg-amber-500',
      text: 'text-amber-600 dark:text-amber-400',
      border: 'border-amber-500/30',
      bg: 'bg-amber-500/10',
      glow: 'shadow-amber-500/15',
    };
  }
  return {
    label: 'High Risk: Tight Connection',
    color: 'danger',
    bar: 'bg-rose-500',
    text: 'text-rose-600 dark:text-rose-400',
    border: 'border-rose-500/30',
    bg: 'bg-rose-500/10',
    glow: 'shadow-rose-500/15',
  };
}

// Animation variants
const cardVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { delay: Math.min(i * 0.05, 0.25), duration: 0.3, ease: 'easeOut' as const },
  }),
};

const expandVariants = {
  hidden: { opacity: 0, height: 0, y: -6 },
  visible: { opacity: 1, height: 'auto', y: 0, transition: { duration: 0.25, ease: 'easeOut' as const } },
  exit: { opacity: 0, height: 0, y: -6, transition: { duration: 0.18, ease: 'easeIn' as const } },
};

// Route quality warnings
function RouteWarnings({
  split,
  date,
  getLegData,
  availabilityMap,
  selectedClassByLeg,
  selectedClass,
  unavailable,
}: any) {
  if (unavailable) return null;
  const waitTime = Number(split.wait_time ?? split.bufferMinutes ?? 0);
  const isWeeklyTrain = (name: string) => {
    if (!name) return false;
    const n = name.toLowerCase();
    return (
      n.includes('weekly') ||
      n.includes('biweekly') ||
      n.includes('triweekly') ||
      n.includes('bi-weekly') ||
      n.includes('wkly')
    );
  };
  const legs = split.legs || split.trains || [];
  const dependsOnWeekly = legs.some((leg: any) => {
    if (!leg) return false;
    const legData = getLegData ? getLegData(leg) : null;
    return (
      isWeeklyTrain(legData?.trainName || '') ||
      isWeeklyTrain(leg.trainName || '') ||
      isWeeklyTrain(leg.name || '')
    );
  });

  const isOvernightConnection = (() => {
    if (legs.length < 2) return false;
    const date1 = legs[0]?.travelDate || date;
    const date2 = legs[1]?.travelDate || date;
    if (date1 && date2 && date1 !== date2) return true;
    const arrTime = legs[0]?.arrival;
    const depTime = legs[1]?.departure;
    if (arrTime && depTime && arrTime !== 'Timing unavailable' && depTime !== 'Timing unavailable') {
      const [arrHour] = arrTime.split(':').map(Number);
      const [depHour] = depTime.split(':').map(Number);
      if ((arrHour >= 21 && depHour <= 8) || arrHour > depHour) return true;
    }
    return false;
  })();

  let combinedChance = 100;
  let hasAvailabilityData = false;
  legs.forEach((leg: any) => {
    const legData = getLegData ? getLegData(leg) : null;
    if (!legData) return;
    const paddedTrainNo = cleanTrainNo(legData.trainNo);
    const currentClass = selectedClassByLeg[`${paddedTrainNo}_${legData.from}_${legData.to}`] || selectedClass;
    const queryDate = leg.travelDate || date;
    const key = `${paddedTrainNo}_${legData.from}_${legData.to}_${currentClass}_${queryDate}`;
    const avail = legData.trainNo ? availabilityMap[key] : null;
    if (avail && Object.keys(avail).length > 0 && !('error' in avail)) {
      hasAvailabilityData = true;
      const bestChance = Math.max(...Object.values(avail).map((v: any) => v.chance || 0));
      if (bestChance < combinedChance) combinedChance = bestChance;
    }
  });

  const successPercent = split.success_percent ? Number(split.success_percent) : null;
  const isLowSuccess =
    (successPercent !== null && successPercent < 75) ||
    (hasAvailabilityData && combinedChance < 75 && combinedChance !== 100);

  if (waitTime <= 360 && !dependsOnWeekly && !isOvernightConnection && !isLowSuccess) return null;

  const warnings = [
    waitTime > 360 && waitTime <= 720 && {
      color: 'amber',
      icon: <Clock className="w-4 h-4 mt-0.5 shrink-0" />,
      text: (
        <>
          <strong>Extended connection wait:</strong> Wait of {Math.round(waitTime / 60)}h detected. Please verify
          comfort and station facilities.
        </>
      ),
    },
    waitTime > 720 && {
      color: 'rose',
      icon: <Clock className="w-4 h-4 mt-0.5 shrink-0" />,
      text: (
        <>
          <strong>Long layover:</strong> Wait of {Math.round(waitTime / 60)}h detected. Station retiring room or hotel
          stay recommended.
        </>
      ),
    },
    dependsOnWeekly && {
      color: 'blue',
      icon: <Info className="w-4 h-4 mt-0.5 shrink-0" />,
      text: (
        <>
          <strong>Weekly Train Dependency:</strong> Verify operating days before booking.
        </>
      ),
    },
    isOvernightConnection && {
      color: 'blue',
      icon: <Info className="w-4 h-4 mt-0.5 shrink-0" />,
      text: (
        <>
          <strong>Overnight connection:</strong> You will spend part of the night at the transit station.
        </>
      ),
    },
    isLowSuccess && {
      color: 'amber',
      icon: <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />,
      text: (
        <>
          <strong>Lower connection probability:</strong> Historical data indicates higher risk of connecting train
          delay.
        </>
      ),
    },
  ].filter(Boolean) as Array<{ color: string; icon: React.ReactNode; text: React.ReactNode }>;

  const colorMap: Record<string, string> = {
    amber: 'bg-amber-500/10 border-amber-500/30 text-amber-700 dark:text-amber-400',
    rose: 'bg-rose-500/10 border-rose-500/30 text-rose-700 dark:text-rose-400',
    blue: 'bg-blue-500/10 border-blue-500/30 text-blue-700 dark:text-blue-400',
  };

  return (
    <div className="flex flex-col gap-2 mb-4">
      {warnings.map((w, i) => (
        <div
          key={i}
          className={clsx('p-3 rounded-xl text-xs flex items-start gap-2.5 shadow-xs border', colorMap[w.color])}
        >
          {w.icon}
          <div className="leading-relaxed">{w.text}</div>
        </div>
      ))}
    </div>
  );
}

export const SplitJourneyCard = ({
  split,
  date,
  availabilityMap,
  availCacheRef,
  loadingTrain,
  handleCheckAvailability,
  getTrainInfo,
  getLegData,
  getCode,
  getRiskColor,
  safeDuration,
  selectedClassByLeg,
  setSelectedClassByLeg,
  selectedClass = 'SL',
  selectedQuota = 'GN',
  cardIndex = 0,
  handleBooking,
}: {
  split: any;
  date: string;
  availabilityMap: any;
  availCacheRef?: any;
  loadingTrain: Record<string, boolean>;
  handleCheckAvailability: (params: any) => void;
  getTrainInfo: (train: any) => any;
  getLegData: (leg: any) => any;
  getCode: (val: any) => string;
  getRiskColor: (risk: string) => string;
  safeDuration: (val: any, backup?: any) => string | null;
  selectedClassByLeg: Record<string, string>;
  setSelectedClassByLeg: React.Dispatch<React.SetStateAction<Record<string, string>>>;
  selectedClass?: string;
  selectedQuota?: string;
  cardIndex?: number;
  handleBooking?: (split: any) => void;
}) => {
  const [expanded, setExpanded] = useState(false);
  const [showBoardingPassModal, setShowBoardingPassModal] = useState(false);

  const legs =
    split.legs && split.legs.length > 0
      ? split.legs
      : split.trains && split.trains.length > 0
      ? split.trains
      : split.segments && split.segments.length > 0
      ? split.segments
      : split.leg1 && split.leg2
      ? [split.leg1, split.leg2]
      : [];

  const bufferMins = Number(split.wait_time ?? split.bufferMinutes ?? 0);
  const bufferMeta = getBufferMeta(bufferMins);
  const isSameTrain =
    split.isSameTrain === true ||
    split.rescueType === 'SAME_TRAIN_SEGMENT' ||
    (legs[0] && legs[1] && getLegData(legs[0])?.trainNo === getLegData(legs[1])?.trainNo);

  // Station identities
  const rawHub = split.hub || split.via || '';
  const hubDetails = getStationDetails(rawHub, split.hubName || split.hub_name);
  const hubName = hubDetails.name || rawHub || 'Intermediate Station';
  const hubCode = hubDetails.code || rawHub;

  const firstLeg = legs[0];
  const firstLegData = firstLeg ? getLegData(firstLeg) : null;
  const originCode = firstLegData?.fromCode || firstLeg?.fromCode || firstLegData?.from || split.source || '';
  const originDetails = getStationDetails(originCode, firstLeg?.fromName || firstLegData?.fromName);

  const lastLeg = legs[legs.length - 1];
  const lastLegData = lastLeg ? getLegData(lastLeg) : null;
  const destCode = lastLegData?.toCode || lastLeg?.toCode || lastLegData?.to || split.destination || '';
  const destDetails = getStationDetails(destCode, lastLeg?.toName || lastLegData?.toName);

  // Availability calculation
  let combinedChance = 100;
  let missing = false;
  let unavailable = false;
  legs.forEach((leg: any, lIdx: number) => {
    const legData = getLegData(leg);
    if (!legData) return;
    const paddedTrainNo = cleanTrainNo(legData.trainNo);
    const hub = split.hub || split.via;
    const legFrom =
      lIdx === 1 && hub && (!legData.fromCode || legData.fromCode === split.source)
        ? hub
        : legData.fromCode || legData.from;
    const legTo =
      lIdx === 0 && hub && (!legData.toCode || legData.toCode === split.destination)
        ? hub
        : legData.toCode || legData.to;
    const currentClass = selectedClassByLeg[`${paddedTrainNo}_${legFrom}_${legTo}`] || selectedClass;
    const queryDate =
      leg.travelDate ||
      leg.journeyDate ||
      (lIdx === 1 ? split.leg2?.travelDate || split.leg2?.journeyDate : split.leg1?.travelDate || split.leg1?.journeyDate) ||
      date;
    const key = `${paddedTrainNo}_${legFrom}_${legTo}_${currentClass}_${queryDate}`;
    const avail = legData.trainNo ? availabilityMap[key] : null;

    if (!avail || Object.keys(avail).length === 0) {
      missing = true;
    } else if ('error' in avail) {
      if (avail.type === 'unavailable' && (avail.reason === 'REGRET' || avail.reason === 'TRAIN_CANCELLED')) {
        unavailable = true;
      } else {
        missing = true;
      }
    } else {
      const bestChance = Math.max(...Object.values(avail).map((v: any) => v.chance || 0));
      if (bestChance < combinedChance) combinedChance = bestChance;

      const statuses = Object.values(avail).map((v: any) => String(v.status || '').toUpperCase());
      const isRegret = statuses.some(
        (s) => s.includes('REGRET') || s.includes('NOT AVAILABLE') || s.includes('CLASS NOT AVAILABLE')
      );
      if (isRegret) {
        unavailable = true;
      }
    }
  });

  const verifiedAvailable = !missing && !unavailable;
  const showRecommendations = verifiedAvailable && combinedChance >= 45;

  // Fare calculations
  const calculateFares = () => {
    let leg1Fare: number | null = null;
    let leg2Fare: number | null = null;

    if (legs.length >= 2) {
      const l1Data = getLegData(legs[0]);
      const l2Data = getLegData(legs[1]);
      const p1 = cleanTrainNo(l1Data?.trainNo);
      const p2 = cleanTrainNo(l2Data?.trainNo);
      const hub = split.hub || split.via;
      const l1From = l1Data?.fromCode || l1Data?.from || split.source;
      const l1To = hub || l1Data?.toCode || l1Data?.to;
      const l2From = hub || l2Data?.fromCode || l2Data?.from;
      const l2To = l2Data?.toCode || l2Data?.to || split.destination;

      const c1 = selectedClassByLeg[`${p1}_${l1From}_${l1To}`] || selectedClass;
      const c2 = selectedClassByLeg[`${p2}_${l2From}_${l2To}`] || selectedClass;

      const d1 = legs[0]?.travelDate || date;
      const d2 = legs[1]?.travelDate || date;

      const a1 = availabilityMap[`${p1}_${l1From}_${l1To}_${c1}_${d1}`];
      const a2 = availabilityMap[`${p2}_${l2From}_${l2To}_${c2}_${d2}`];

      const getFareVal = (avail: any, legObj: any, lData: any) => {
        if (avail && typeof avail === 'object') {
          const f = avail.fare;
          if (typeof f === 'number') return f;
          if (typeof f === 'string') {
            const n = parseInt(f.replace(/\D/g, ''), 10);
            if (!isNaN(n)) return n;
          }
        }
        const raw = legObj?.fare ?? lData?.fare;
        if (typeof raw === 'number') return raw;
        if (typeof raw === 'string') {
          const n = parseInt(raw.replace(/\D/g, ''), 10);
          if (!isNaN(n)) return n;
        }
        return null;
      };

      leg1Fare = getFareVal(a1, legs[0], l1Data);
      leg2Fare = getFareVal(a2, legs[1], l2Data);
    }

    const rootFare = split.fare ?? split.totalFare ?? split.total_fare;
    const rootFareNum =
      typeof rootFare === 'number'
        ? rootFare
        : typeof rootFare === 'string'
        ? parseInt(rootFare.replace(/\D/g, ''), 10)
        : null;

    const totalFare =
      leg1Fare !== null && leg2Fare !== null
        ? leg1Fare + leg2Fare
        : rootFareNum || (leg1Fare ?? leg2Fare ?? null);

    return { leg1Fare, leg2Fare, totalFare };
  };

  const { leg1Fare, leg2Fare, totalFare } = calculateFares();

  // Multi-day date rollover check
  const isOvernightConnection = (() => {
    if (legs.length < 2) return false;
    const date1 = legs[0]?.travelDate || date;
    const date2 = legs[1]?.travelDate || date;
    if (date1 && date2 && date1 !== date2) return true;
    const arrTime = legs[0]?.arrival;
    const depTime = legs[1]?.departure;
    if (arrTime && depTime && arrTime !== 'Timing unavailable' && depTime !== 'Timing unavailable') {
      const [arrHour] = arrTime.split(':').map(Number);
      const [depHour] = depTime.split(':').map(Number);
      if ((arrHour >= 21 && depHour <= 8) || arrHour > depHour) return true;
    }
    return false;
  })();

  // Total duration calculation
  const totalDurationText = (() => {
    const parseMins = (val: any): number => {
      if (!val) return 0;
      if (typeof val === 'number') return val;
      const str = String(val).toLowerCase().trim();
      let mins = 0;
      const hMatch = str.match(/(\d+)\s*h/);
      const mMatch = str.match(/(\d+)\s*m/);
      if (hMatch) mins += parseInt(hMatch[1], 10) * 60;
      if (mMatch) mins += parseInt(mMatch[1], 10);
      const colonMatch = str.match(/(\d+)\s*:\s*(\d+)/);
      if (colonMatch) mins = parseInt(colonMatch[1], 10) * 60 + parseInt(colonMatch[2], 10);
      if (!hMatch && !mMatch && !colonMatch) {
        const num = parseInt(str, 10);
        if (!isNaN(num)) mins = num;
      }
      return mins;
    };
    const legsMins = legs.reduce(
      (sum: number, leg: any) => sum + parseMins(leg.duration_mins || leg.duration || leg.durationMins || 0),
      0
    );
    const waitMins = parseMins(split.wait_time || split.bufferMinutes || 0);
    const totalMins = legsMins + waitMins;
    return totalMins > 0
      ? safeDuration(totalMins)
      : split.total_duration || safeDuration(split.totalDuration, null) || 'Timing unavailable';
  })();

  // Leg-wise detailed availability helper
  const getLegAvailabilityDetails = (legIndex: number) => {
    const leg = legs[legIndex];
    if (!leg) return null;
    const legData = getLegData ? getLegData(leg) : leg;
    const paddedTrainNo = cleanTrainNo(legData?.trainNo || leg?.trainNo || leg?.trainNumber);
    const info = getTrainInfo ? getTrainInfo(leg) : { number: paddedTrainNo, name: legData?.trainName || leg?.trainName || 'Connecting Express' };
    const trainName = info?.name || legData?.trainName || leg?.trainName || 'Connecting Express';
    const hub = split.hub || split.via;

    const legFromCode = legIndex === 1 && hub && (!legData?.fromCode || legData?.fromCode === split.source)
      ? hub
      : legData?.fromCode || legData?.from || (legIndex === 0 ? split.source : hub);

    const legToCode = legIndex === 0 && hub && (!legData?.toCode || legData?.toCode === split.destination)
      ? hub
      : legData?.toCode || legData?.to || (legIndex === 1 ? split.destination : hub);

    const legFromDetails = getStationDetails(legFromCode, leg?.fromName || legData?.fromName);
    const legToDetails = getStationDetails(legToCode, leg?.toName || legData?.toName);

    const depTime = leg?.departure || legData?.departure || 'Departure';
    const arrTime = leg?.arrival || legData?.arrival || 'Arrival';

    const legSupportedClasses = getTrainSupportedClasses({
      trainNumber: paddedTrainNo || info?.number,
      trainName,
      classes: leg?.classes,
    });

    const legKey = `${paddedTrainNo}_${legFromCode}_${legToCode}`;
    const currentClass = getDefaultActiveClass(legSupportedClasses, selectedClassByLeg[legKey] || selectedClass);
    const queryDate =
      leg.travelDate ||
      leg.journeyDate ||
      (legIndex === 1 ? (split.leg2?.travelDate || split.leg2?.journeyDate) : (split.leg1?.travelDate || split.leg1?.journeyDate)) ||
      date;

    const legQuota = (leg?.quota || split?.quota || selectedQuota || 'GN').toUpperCase().trim();
    const specificAvailKey = `${legKey}_${currentClass}_${queryDate}_${legQuota}`;
    const legacyAvailKey = `${legKey}_${currentClass}_${queryDate}`;
    const availKey = legQuota === 'GN' ? legacyAvailKey : specificAvailKey;
    const isLoading = !!loadingTrain[specificAvailKey] || !!loadingTrain[legacyAvailKey];

    // Lookup in availabilityMap
    let avail = availabilityMap[specificAvailKey] ?? (legQuota === 'GN' ? availabilityMap[legacyAvailKey] : undefined);
    let displayClass = currentClass;

    if (!avail) {
      const fallbackKey = Object.keys(availabilityMap).find((k) =>
        k.startsWith(`${legKey}_`) && (legQuota === 'GN' ? (k.endsWith(`_${queryDate}`) || k.endsWith(`_${queryDate}_GN`)) : k.endsWith(`_${queryDate}_${legQuota}`)) && availabilityMap[k] && !availabilityMap[k].error
      );
      if (fallbackKey) {
        avail = availabilityMap[fallbackKey];
        const parts = fallbackKey.substring(legKey.length + 1).split('_');
        displayClass = parts[0];
      }
    }

    let status: string | null = null;
    let fare: number | string | null = null;
    let isVerified = false;
    let isRegret = false;
    let isConfirmed = false;
    let isRac = false;
    let isWaitlisted = false;
    let isError = false;
    let errorMsg = '';

    if (avail && !('error' in avail)) {
      const val = (avail as any)[displayClass] || Object.values(avail).find((v: any) => v && typeof v === 'object' && v.status);
      if (val && val.status) {
        status = String(val.status);
        isVerified = true;
        const cls = classifyAvailability(val.status);
        isConfirmed = cls.isAvailable || cls.isConfirmed;
        isRac = cls.isRac;
        isWaitlisted = cls.isWaitlisted;
        isRegret = cls.isTerminal;
        fare = typeof val.fare === 'object' && val.fare !== null
          ? (val.fare.totalFare ?? val.fare.total_fare ?? val.fare.total ?? null)
          : (typeof val.fare === 'number' || typeof val.fare === 'string' ? val.fare : null);
      }
    } else if (avail && 'error' in avail) {
      status = avail.type === 'unavailable' ? 'Not Available' : 'Error Checking';
      isRegret = true;
      isError = true;
      errorMsg = avail.message || 'Availability check failed';
    } else {
      // Check initial estimated availability
      const initialAvail = leg.availability || legData?.availability;
      const initialStatus = typeof initialAvail === 'string' ? initialAvail : (initialAvail?.status || initialAvail?.[currentClass]?.status || '');
      if (initialStatus) {
        status = String(initialStatus);
        isVerified = false;
        const cls = classifyAvailability(initialStatus);
        isConfirmed = cls.isAvailable || cls.isConfirmed;
        isRac = cls.isRac;
        isWaitlisted = cls.isWaitlisted;
        isRegret = cls.isTerminal;
        fare = typeof initialAvail === 'object' ? (initialAvail?.fare || initialAvail?.[currentClass]?.fare) : (leg.fare || legData?.fare || null);
      }
    }

    return {
      legIndex,
      legQuota,
      trainNo: paddedTrainNo || info?.number,
      trainName,
      fromCode: legFromCode,
      fromName: legFromDetails.name,
      toCode: legToCode,
      toName: legToDetails.name,
      depTime,
      arrTime,
      date: queryDate,
      currentClass: displayClass,
      supportedClasses: legSupportedClasses,
      status,
      fare,
      isVerified,
      isConfirmed,
      isRac,
      isWaitlisted,
      isRegret,
      isError,
      errorMsg,
      isLoading,
      availKey,
      onCheck: () => {
        handleCheckAvailability({
          trainNo: paddedTrainNo,
          from: legFromCode,
          to: legToCode,
          classType: displayClass,
          travelDate: queryDate,
          quota: legQuota,
        });
      },
      onSelectClass: (newCls: string) => {
        setSelectedClassByLeg((prev) => ({ ...prev, [legKey]: newCls }));
        handleCheckAvailability({
          trainNo: paddedTrainNo,
          from: legFromCode,
          to: legToCode,
          classType: newCls,
          travelDate: queryDate,
          quota: legQuota,
        });
      },
    };
  };

  const leg1Details = getLegAvailabilityDetails(0);
  const leg2Details = getLegAvailabilityDetails(1);
  const hasWaitlistedLeg = Boolean(leg1Details?.isWaitlisted || leg2Details?.isWaitlisted);
  const areBothLegsConfirmed = Boolean(leg1Details?.isConfirmed && leg2Details?.isConfirmed);

  return (
    <motion.div
      id={split.id ? `split-card-${split.id}` : cardIndex !== undefined ? `split-card-${cardIndex}` : undefined}
      custom={cardIndex}
      variants={cardVariants}
      initial="hidden"
      animate="visible"
      className={clsx(
        'relative bg-card border rounded-3xl overflow-hidden transition-all duration-200 shadow-sm',
        isSameTrain
          ? 'border-emerald-500/35 hover:border-emerald-500/55'
          : showRecommendations && split.isBest
          ? 'border-blue-500/40 hover:border-blue-500/60'
          : 'border-slate-200/90 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700'
      )}
    >
      {/* Featured Route Border Beam */}
      {(split.isBest || cardIndex === 0) && (
        <BorderBeam
          size={280}
          duration={10}
          colorFrom="#3b82f6"
          colorTo="#10b981"
        />
      )}

      {/* Lock Overlay */}
      {split.isLocked && !isPaidOrAdminUser() && (
        <div className="absolute inset-0 bg-slate-950/75 backdrop-blur-[6px] rounded-3xl flex flex-col items-center justify-center p-6 text-center z-30 border border-primary/30">
          <div className="w-12 h-12 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center mb-3">
            <Lock size={20} className="text-primary" />
          </div>
          <h4 className="font-extrabold text-main text-lg mb-1">AI Split Route Found</h4>
          <p className="text-muted text-xs mb-4 max-w-[240px]">
            This connection was optimized by AI. Unlock details to see trains, exact timings, and official booking steps.
          </p>
          <Button
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
              const userRaw = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
              if (!userRaw || userRaw === 'undefined' || userRaw === 'null') {
                window.location.href = '/signup';
              } else {
                window.location.href = '/pricing';
              }
            }}
            variant="primary"
            size="sm"
            className="px-5 border border-primary/25 rounded-xl cursor-pointer active:scale-95"
          >
            {(() => {
              if (typeof window === 'undefined') return 'Claim Free Trial (Sign Up)';
              const userRaw = localStorage.getItem('user');
              const userObj = userRaw && userRaw !== 'undefined' && userRaw !== 'null' ? JSON.parse(userRaw) : null;
              if (!userObj) return 'Claim Free Trial (Sign Up)';
              if (isPaidOrAdminUser(userObj)) return 'Unlock Route';
              return 'Upgrade to Safar Pro';
            })()}
          </Button>
        </div>
      )}

      {/* ZONE 1: TOP IDENTITY HEADER BAR */}
      <div
        className={clsx(
          'flex flex-wrap items-center justify-between gap-2 px-5 sm:px-6 py-2.5 border-b',
          isSameTrain
            ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-700 dark:text-emerald-400'
            : 'bg-primary/10 border-primary/20 text-primary'
        )}
      >
        <div className="flex items-center gap-2">
          <Train className="w-4 h-4 shrink-0" />
          <span className="text-xs font-black uppercase tracking-wider">
            {isSameTrain
              ? 'Same-Train Seat Rescue: Zero Train Change'
              : '2-Train Connecting Split: Verified Layover'}
          </span>
        </div>

        <div className="flex items-center gap-2 text-xs font-bold">
          {split.isBest && (
            <span className="bg-emerald-500/20 text-emerald-700 dark:text-emerald-300 px-2.5 py-0.5 rounded-full border border-emerald-500/30 text-[10px] font-black uppercase tracking-wider flex items-center gap-1">
              <Sparkles className="w-3 h-3 text-emerald-500" /> Top Choice
            </span>
          )}
          <span className="font-mono text-[11px] font-extrabold">
            {isSameTrain ? 'Stay On Board' : `${bufferMins}m buffer`}
          </span>
        </div>
      </div>

      {/* CARD MAIN BODY */}
      <div className={clsx('p-5 sm:p-7', split.isLocked && 'filter blur-sm pointer-events-none select-none opacity-40')}>
        {/* ROUTE TITLE & METRICS SUMMARY ROW */}
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 pb-4 mb-4 border-b border-subtle">
          <div>
            <div className="flex items-center gap-2 text-xs font-bold text-muted mb-1 flex-wrap">
              <span>Connecting Route</span>
              {isOvernightConnection && (
                <span className="px-2 py-0.5 rounded-full bg-blue-500/10 border border-blue-500/25 text-blue-600 dark:text-blue-400 text-[10px] font-black uppercase tracking-wider flex items-center gap-1">
                  <Calendar className="w-3 h-3" /> Next Day Departure (+1 Day)
                </span>
              )}
            </div>

            <h3 className="text-lg sm:text-xl font-black text-main tracking-tight flex items-center gap-2 flex-wrap">
              <span>{originDetails.name}</span>
              {originDetails.code && <span className="font-mono text-xs text-muted">({originDetails.code})</span>}
              <ArrowRight className="w-4 h-4 text-primary shrink-0" />
              <span className={isSameTrain ? 'text-emerald-600 dark:text-emerald-400' : 'text-primary'}>
                {hubName}
              </span>
              {hubCode && (
                <span className="font-mono text-xs px-1.5 py-0.5 rounded bg-input border border-subtle text-main">
                  ({hubCode})
                </span>
              )}
              <ArrowRight className="w-4 h-4 text-primary shrink-0" />
              <span>{destDetails.name}</span>
              {destDetails.code && <span className="font-mono text-xs text-muted">({destDetails.code})</span>}
            </h3>
          </div>

          {/* Quick Metrics Summary Pills */}
          <div className="flex flex-wrap items-center gap-2">
            {/* Total Duration Pill */}
            <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-input border border-subtle text-xs font-bold text-main">
              <Clock className="w-3.5 h-3.5 text-primary shrink-0" />
              <span className="tabular-nums">{totalDurationText}</span>
            </div>

            {/* Total Fare Pill */}
            {totalFare !== null && (
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-500/10 border border-emerald-500/25 text-xs font-black text-emerald-700 dark:text-emerald-400">
                <span className="font-mono text-sm tabular-nums">₹{totalFare}</span>
                <span className="text-[10px] font-bold text-emerald-600/80 dark:text-emerald-400/80">Total</span>
              </div>
            )}

            {/* Confirmation Chance Pill */}
            {split.confirmation_probability !== undefined ? (
              <div
                className={clsx(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold border tabular-nums',
                  split.confirmation_probability >= 75
                    ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-700 dark:text-emerald-400'
                    : 'bg-amber-500/10 border-amber-500/30 text-amber-700 dark:text-amber-400'
                )}
              >
                <CheckCircle2 className="w-3.5 h-3.5 shrink-0" />
                <span className="tabular-nums">{split.confirmation_probability}% Confirmed</span>
              </div>
            ) : split.success_percent ? (
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-input border border-subtle text-xs font-bold text-main tabular-nums">
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500 shrink-0" />
                <span className="tabular-nums">{split.success_percent}% Match</span>
              </div>
            ) : null}
          </div>
        </div>

        {/* PLAIN-ENGLISH HUMANIZED REASSURANCE BANNER */}
        <div
          className={clsx(
            'p-3.5 rounded-2xl border text-xs sm:text-sm font-medium mb-5 flex items-start gap-3',
            isSameTrain
              ? 'bg-slate-50 dark:bg-slate-900/60 border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200'
              : hasWaitlistedLeg
              ? 'bg-amber-500/10 border-amber-500/30 text-amber-900 dark:text-amber-200'
              : 'bg-primary/5 border-primary/20 text-secondary'
          )}
        >
          {isSameTrain ? (
            <ShieldCheck className="w-5 h-5 text-emerald-600 dark:text-emerald-400 shrink-0 mt-0.5" />
          ) : hasWaitlistedLeg ? (
            <AlertTriangle className="w-5 h-5 text-amber-600 dark:text-amber-400 shrink-0 mt-0.5" />
          ) : (
            <Info className="w-5 h-5 text-primary shrink-0 mt-0.5" />
          )}
          <div className="space-y-0.5 leading-relaxed">
            <strong className="block font-black text-main">
              {isSameTrain
                ? 'Zero Train Change: You stay on this train for the entire journey!'
                : hasWaitlistedLeg
                ? `Connecting Route: ${bufferMins} min layover at ${hubName} (Waitlisted Segments Present)`
                : `Verified connection: ${bufferMins} min comfortable layover at ${hubName}`}
            </strong>
            <p className="text-xs text-muted">
              {isSameTrain
                ? `You book 2 seat segments on this exact train. When the train reaches ${hubName}, you simply switch to your second seat. You do NOT leave the train.`
                : hasWaitlistedLeg
                ? `Board Train 1 to ${hubName}, change platforms during your ${bufferMins}m layover, and board Train 2 to ${destDetails.name}. Please note: One or more legs currently have waitlisted status. Check confirmation chances before booking.`
                : `Board Train 1 to ${hubName}, change platforms during your ${bufferMins}m layover, and board Train 2 to ${destDetails.name}. Both legs have confirmed seat availability.`}
            </p>
          </div>
        </div>

        {/* ── CRUCIAL: LEG-WISE AVAILABILITY BREAKDOWN ── */}
        <div className="bg-slate-50 dark:bg-slate-900/60 border border-slate-200/90 dark:border-slate-800 rounded-2xl p-4 sm:p-5 mb-5 shadow-xs">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-3.5 pb-3 border-b border-slate-200/80 dark:border-slate-800">
            <div className="flex items-center gap-2">
              <div className="p-1.5 rounded-lg bg-primary/10 text-primary border border-primary/20 shrink-0">
                <Ticket className="w-4 h-4" />
              </div>
              <div>
                <h4 className="text-xs sm:text-sm font-black text-slate-900 dark:text-slate-100 uppercase tracking-tight">
                  Leg-Wise Seat Availability Status
                </h4>
                <p className="text-[11px] text-slate-500 dark:text-slate-400 font-medium">
                  Verified availability per train segment across your connecting route
                </p>
              </div>
            </div>

            {/* Batch Verify Button when any leg is unverified */}
            {(!leg1Details?.isVerified || !leg2Details?.isVerified) && (
              <button
                type="button"
                onClick={() => {
                  if (leg1Details && !leg1Details.isVerified && !leg1Details.isLoading) leg1Details.onCheck();
                  if (leg2Details && !leg2Details.isVerified && !leg2Details.isLoading) leg2Details.onCheck();
                }}
                disabled={leg1Details?.isLoading || leg2Details?.isLoading}
                className="self-start sm:self-auto inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold bg-primary/10 hover:bg-primary/20 text-primary border border-primary/25 cursor-pointer active:scale-95 transition-all shadow-xs disabled:opacity-50 min-h-[36px]"
              >
                {leg1Details?.isLoading || leg2Details?.isLoading ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin text-primary" />
                    <span>Checking Both Legs...</span>
                  </>
                ) : (
                  <>
                    <RefreshCw className="w-3.5 h-3.5 text-primary" />
                    <span>Verify Both Legs Live</span>
                  </>
                )}
              </button>
            )}
          </div>

          {/* Two Leg Cards Grid (Desktop Two-Column, Mobile Single-Column) */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {[leg1Details, leg2Details].filter(Boolean).map((legInfo, idx) => {
              if (!legInfo) return null;
              const parsed = parseRailwayAvailability(legInfo.status);
              return (
                <div
                  key={idx}
                  className="p-4 rounded-xl border bg-white dark:bg-slate-800/90 border-slate-200 dark:border-slate-700 transition-all flex flex-col justify-between gap-3 shadow-xs"
                >
                  {/* Top: Leg Tag, Train Number, Name, Route */}
                  <div>
                    <div className="flex items-start justify-between gap-2 mb-1.5">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span className="px-2 py-0.5 rounded-md bg-primary/10 text-primary border border-primary/20 text-[10px] font-black uppercase tracking-wider">
                          Leg {idx + 1}
                        </span>
                        <span
                          className={clsx(
                            "px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider border leading-none font-mono",
                            legInfo.legQuota === 'TQ' ? "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/25" :
                            legInfo.legQuota === 'LD' ? "bg-pink-500/10 text-pink-600 dark:text-pink-400 border-pink-500/25" :
                            legInfo.legQuota === 'SS' ? "bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/25" :
                            "bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/25"
                          )}
                          title={`Quota: ${legInfo.legQuota || 'GN'}`}
                        >
                          {legInfo.legQuota || 'GN'}
                        </span>
                        <span className="font-mono text-xs font-black text-slate-900 dark:text-slate-100 tabular-nums">
                          #{legInfo.trainNo}
                        </span>
                      </div>
                      <div className="text-right shrink-0">
                        <span className="font-mono text-xs font-black text-slate-900 dark:text-slate-100 tabular-nums block">
                          {legInfo.depTime} → {legInfo.arrTime}
                        </span>
                        <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 tabular-nums">
                          {legInfo.date}
                        </span>
                      </div>
                    </div>

                    <h5 className="text-xs sm:text-sm font-extrabold text-slate-900 dark:text-slate-100 truncate mb-1">
                      {legInfo.trainName}
                    </h5>

                    <div className="text-[11px] font-semibold text-slate-600 dark:text-slate-300 flex items-center gap-1 flex-wrap">
                      <span className="font-bold text-slate-900 dark:text-slate-100">{legInfo.fromName}</span>
                      {legInfo.fromCode && (
                        <span className="font-mono text-[10px] text-slate-500">({legInfo.fromCode})</span>
                      )}
                      <ArrowRight className="w-3 h-3 text-slate-400 shrink-0" />
                      <span className="font-bold text-slate-900 dark:text-slate-100">{legInfo.toName}</span>
                      {legInfo.toCode && (
                        <span className="font-mono text-[10px] text-slate-500">({legInfo.toCode})</span>
                      )}
                    </div>
                  </div>

                  {/* Dedicated Leg Availability Status Section (Seats vs Waitlist) */}
                  <div className="p-3 rounded-xl border bg-slate-50 dark:bg-slate-900/60 border-slate-200 dark:border-slate-800 flex flex-col gap-1.5">
                    <div className="flex items-center justify-between gap-1.5 flex-wrap">
                      <span className={clsx(
                        "inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-black tracking-wide border tabular-nums shadow-xs",
                        parsed.badgeClass
                      )}>
                        {parsed.iconSymbol} {parsed.headline}
                      </span>
                      <span className={clsx(
                        "text-[9px] font-black uppercase tracking-wider",
                        legInfo.isVerified ? "text-emerald-700 dark:text-emerald-400" : "text-slate-500"
                      )}>
                        {legInfo.isVerified ? "● Live Verified" : "○ Estimated"}
                      </span>
                    </div>

                    <div className="flex items-baseline justify-between gap-1 pt-1 border-t border-slate-200/70 dark:border-slate-800 text-xs">
                      <span className="font-extrabold text-slate-900 dark:text-slate-100">
                        {parsed.seatSummary}
                      </span>
                      {legInfo.fare && (
                        <span className="font-mono font-black text-slate-900 dark:text-white shrink-0 tabular-nums">
                          ₹{legInfo.fare}
                        </span>
                      )}
                    </div>

                    {legInfo.isError && (
                      <div className="text-[10px] text-rose-500 font-bold bg-rose-500/10 p-1.5 rounded border border-rose-500/20">
                        ⚠️ Check Failed: {legInfo.errorMsg}
                      </div>
                    )}

                    <p className="text-[10px] text-slate-600 dark:text-slate-400 leading-snug">
                      {parsed.explanation}
                    </p>
                  </div>

                  {/* Bottom: Class Select & Live Check Trigger */}
                  <div className="flex items-center justify-between gap-2 pt-2 border-t border-slate-200/70 dark:border-slate-700/70">
                    <div className="flex items-center gap-1.5">
                      <span className="text-[10px] font-black uppercase tracking-wider text-slate-500 dark:text-slate-400">Class</span>
                      <select
                        value={legInfo.currentClass}
                        onChange={(e) => legInfo.onSelectClass(e.target.value)}
                        aria-label={`Select class for Leg ${idx + 1}`}
                        className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-slate-100 text-[11px] font-black rounded-lg px-2 py-1 outline-none focus:border-primary cursor-pointer shadow-xs min-h-[32px]"
                      >
                        {legInfo.supportedClasses.map((cls: string) => (
                          <option key={cls} value={cls}>
                            Class {cls}
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="flex items-center gap-1.5">
                      {legInfo.isLoading ? (
                        <div className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-primary/10 text-primary text-xs font-bold border border-primary/20">
                          <Loader2 className="w-3 h-3 animate-spin text-primary" />
                          <span>Checking...</span>
                        </div>
                      ) : (
                        <button
                          type="button"
                          id={`check-avail-leg${idx + 1}-${split.id || cardIndex || 0}-${legInfo.trainNo}`}
                          onClick={legInfo.onCheck}
                          className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold text-primary hover:text-white bg-primary/10 hover:bg-primary border border-primary/25 transition-all cursor-pointer shadow-xs min-h-[32px]"
                        >
                          <RefreshCw className="w-3 h-3 text-primary group-hover:text-white" />
                          <span>{legInfo.isError ? 'Retry Check' : legInfo.isVerified ? 'Recheck Availability' : 'Check Availability'}</span>
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Passenger Safety Alert when any leg is waitlisted */}
          {hasWaitlistedLeg && (
            <div className="mt-3.5 p-3 rounded-xl bg-amber-500/10 border border-amber-500/30 flex items-start gap-2.5 text-xs text-amber-800 dark:text-amber-300 font-medium leading-relaxed">
              <AlertTriangle className="w-4 h-4 text-amber-600 dark:text-amber-400 shrink-0 mt-0.5" />
              <div>
                <strong>Passenger Transparency Warning:</strong> One of your legs is currently <strong>Waitlisted</strong> ({leg1Details?.isWaitlisted ? `Leg 1: ${leg1Details.status}` : ''}{leg1Details?.isWaitlisted && leg2Details?.isWaitlisted ? ' and ' : ''}{leg2Details?.isWaitlisted ? `Leg 2: ${leg2Details.status}` : ''}). You are guaranteed a confirmed seat only on the available leg. Review both legs carefully before proceeding to official booking.
              </div>
            </div>
          )}

          {/* Fully Confirmed Indicator when both legs are available */}
          {areBothLegsConfirmed && (
            <div className="mt-3.5 p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 flex items-center gap-2 text-xs text-emerald-800 dark:text-emerald-300 font-bold">
              <CheckCircle2 className="w-4 h-4 text-emerald-600 dark:text-emerald-400 shrink-0" />
              <span>
                100% Confirmed Journey: Confirmed seat availability is verified on both Leg 1 and Leg 2!
              </span>
            </div>
          )}
        </div>

        {/* ZONE 2: VERTICAL STATION TIMELINE */}
        <VerticalStationTimeline
          split={split}
          legs={legs}
          date={date}
          availabilityMap={availabilityMap}
          availCacheRef={availCacheRef}
          loadingTrain={loadingTrain}
          handleCheckAvailability={handleCheckAvailability}
          getTrainInfo={getTrainInfo}
          getLegData={getLegData}
          selectedClassByLeg={selectedClassByLeg}
          setSelectedClassByLeg={setSelectedClassByLeg}
          selectedClass={selectedClass}
          safeDuration={safeDuration}
          getBufferMeta={getBufferMeta}
          isSameTrain={isSameTrain}
          unavailable={unavailable}
        />

        {/* ZONE 3: TOTAL FARE BREAKDOWN & ACTION DOCK */}
        <div className="mt-6 pt-5 border-t border-subtle">
          {/* Fare Calculation Math Card */}
          <div className="bg-surface border border-subtle rounded-2xl p-4 mb-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <span className="text-[10px] font-black uppercase tracking-wider text-muted block mb-1">
                Journey Fare Math Breakdown
              </span>
              <div className="text-xs sm:text-sm font-bold text-main flex items-center gap-2 flex-wrap">
                {leg1Fare !== null && leg2Fare !== null ? (
                  <>
                    <span className="text-secondary">
                      Train 1: <strong className="font-mono text-main">₹{leg1Fare}</strong>
                    </span>
                    <span className="text-muted">+</span>
                    <span className="text-secondary">
                      Train 2: <strong className="font-mono text-main">₹{leg2Fare}</strong>
                    </span>
                    <span className="text-muted">=</span>
                    <span className="text-emerald-600 dark:text-emerald-400 font-extrabold text-sm sm:text-base font-mono">
                      ₹{totalFare} Total
                    </span>
                  </>
                ) : totalFare !== null ? (
                  <span className="text-emerald-600 dark:text-emerald-400 font-extrabold text-sm sm:text-base font-mono">
                    Total Estimated Fare: ₹{totalFare}
                  </span>
                ) : (
                  <span className="text-muted text-xs">
                    Fare calculated automatically when class availability is checked
                  </span>
                )}
              </div>
            </div>

            <div className="text-[11px] text-muted font-medium">
              Official IRCTC booking fare without hidden markups
            </div>
          </div>

          {/* Action Row */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <button
              type="button"
              onClick={() => setExpanded((prev) => !prev)}
              className="inline-flex items-center gap-1.5 text-xs font-bold text-muted hover:text-main transition-colors cursor-pointer py-2"
              aria-expanded={expanded}
            >
              {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
              <span>{expanded ? 'Hide Extra Route Details' : 'View Extra Route Details & Warnings'}</span>
            </button>

            <div className="flex items-center gap-2.5 flex-wrap">
              <button
                type="button"
                onClick={() => setShowBoardingPassModal(true)}
                aria-label="View Boarding Pass Ticket"
                className="min-h-[48px] px-4 py-2.5 rounded-xl text-xs sm:text-sm font-bold bg-card hover:bg-input border border-subtle text-main transition-all active:scale-[0.98] cursor-pointer inline-flex items-center gap-2 shadow-xs"
              >
                <Ticket className="w-4 h-4 text-primary" />
                <span>Boarding Pass</span>
              </button>

              {handleBooking && (
                <button
                  type="button"
                  onClick={() => handleBooking(split)}
                  disabled={unavailable}
                  className={clsx(
                    'min-h-[48px] px-6 py-2.5 rounded-xl text-xs sm:text-sm font-extrabold text-white transition-all shadow-md active:scale-[0.98] cursor-pointer inline-flex items-center gap-2',
                    unavailable
                      ? 'bg-input text-muted opacity-50 cursor-not-allowed border border-subtle'
                      : 'bg-primary hover:bg-primary-hover shadow-primary/20'
                  )}
                >
                  <Sparkles className="w-4 h-4" />
                  <span>{unavailable ? 'Route Unavailable' : 'Continue to Official Booking'}</span>
                </button>
              )}
            </div>
          </div>

          {/* ACCORDION: ROUTE WARNINGS, INSIGHTS & STEPS */}
          <AnimatePresence>
            {expanded && (
              <motion.div
                key="details-accordion"
                variants={expandVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
                className="overflow-hidden mt-4 pt-4 border-t border-subtle space-y-4"
              >
                {/* Route Warnings */}
                <RouteWarnings
                  split={split}
                  date={date}
                  getLegData={getLegData}
                  availabilityMap={availabilityMap}
                  selectedClassByLeg={selectedClassByLeg}
                  selectedClass={selectedClass}
                  unavailable={unavailable}
                />

                {/* AI Insight */}
                {split.ai_insight && !unavailable && (
                  <div className="bg-primary/5 border border-primary/15 rounded-xl p-3.5 flex items-start gap-2.5">
                    <Info className="w-4 h-4 text-primary shrink-0 mt-0.5" />
                    <p className="text-xs text-secondary leading-relaxed font-medium">
                      {formatTextWithStations(split.ai_insight)}
                    </p>
                  </div>
                )}

                {/* Booking Steps */}
                {split.steps && !unavailable && (
                  <div className="bg-surface border border-subtle rounded-xl p-3.5">
                    <span className="text-[10px] font-black uppercase tracking-wider text-muted block mb-2">
                      Step-by-Step Booking Instructions
                    </span>
                    <ol className="space-y-1.5 text-xs text-secondary">
                      {split.steps.map((step: string, i: number) => (
                        <li key={i} className="flex items-start gap-2">
                          <span className="text-primary font-bold shrink-0">{i + 1}.</span>
                          <span className="leading-snug">{formatTextWithStations(step)}</span>
                        </li>
                      ))}
                    </ol>
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Boarding Pass Modal */}
      {showBoardingPassModal && (
        <TripBoardingPassModal
          split={split}
          date={date}
          onClose={() => setShowBoardingPassModal(false)}
          onBookOfficial={() => handleBooking && handleBooking(split)}
        />
      )}
    </motion.div>
  );
};

export default SplitJourneyCard;
