'use client';

import { clsx } from 'clsx';
import { ChevronLeft, ChevronRight, Search } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';

interface Seat {
  number: number;
  type: 'LB' | 'MB' | 'UB' | 'SL' | 'SU' | 'W' | 'M' | 'A';
  side?: 'lower' | 'upper';
}

interface SeatMapProps {
  initialCoachType?: string;
  onSeatSelect?: (seat: Seat) => void;
  initialHighlightSeat?: string;
}

export function SeatMap({ initialCoachType = 'SL', onSeatSelect, initialHighlightSeat = '' }: SeatMapProps) {
  const [coachType, setCoachType] = useState(initialCoachType);
  const [highlightSeat, setHighlightSeat] = useState<string>(initialHighlightSeat);
  const scrollRef = useRef<HTMLDivElement>(null);
  const seatRefs = useRef<{ [key: string]: HTMLDivElement | null }>({});

  const coachTypes = ['SL', '3A', '2A', 'CC'];

  const layout = useMemo(() => {
    const seats: Seat[] = [];
    const limit = coachType === 'CC' ? 78 : 72;

    if (coachType === 'SL' || coachType === '3A') {
      for (let i = 1; i <= limit; i++) {
        const mod = i % 8;
        if (mod === 1 || mod === 4) seats.push({ number: i, type: 'LB' });
        else if (mod === 2 || mod === 5) seats.push({ number: i, type: 'MB' });
        else if (mod === 3 || mod === 6) seats.push({ number: i, type: 'UB' });
        else if (mod === 7) seats.push({ number: i, type: 'SL' });
        else seats.push({ number: i, type: 'SU' });
      }
    } else if (coachType === '2A') {
      for (let i = 1; i <= limit; i++) {
        const mod = i % 6;
        if (mod === 1 || mod === 3) seats.push({ number: i, type: 'LB' });
        else if (mod === 2 || mod === 4) seats.push({ number: i, type: 'UB' });
        else if (mod === 5) seats.push({ number: i, type: 'SL' });
        else seats.push({ number: i, type: 'SU' });
      }
    } else if (coachType === 'CC') {
      for (let i = 1; i <= limit; i++) {
        const mod = i % 5;
        if (mod === 1 || mod === 0) seats.push({ number: i, type: 'W' });
        else if (mod === 3) seats.push({ number: i, type: 'M' });
        else seats.push({ number: i, type: 'A' });
      }
    }
    return seats;
  }, [coachType]);

  const getSeatColor = (type: string, isHighlighted: boolean) => {
    if (isHighlighted) return "bg-yellow-400 text-black scale-110 shadow-[0_0_25px_rgba(250,204,21,0.6)] z-20 ring-2 ring-yellow-300";

    switch (type) {
      case 'LB': return "bg-blue-600 dark:bg-[#003366] text-white dark:text-main border border-blue-500/30";
      case 'MB':
      case 'UB': return "bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 border border-blue-300/40 dark:border-blue-400/40";
      case 'SL':
      case 'SU': return "bg-input text-muted border border-subtle";
      case 'W': return "bg-blue-600 dark:bg-[#003366] text-white dark:text-main";
      case 'A': return "bg-emerald-500 dark:bg-emerald-600/80 text-white dark:text-main";
      default: return "bg-input text-muted border border-subtle";
    }
  };

  const scrollToSeat = (num: string) => {
    const seatEl = seatRefs.current[num];
    if (seatEl && scrollRef.current) {
      seatEl.scrollIntoView({
        behavior: 'smooth',
        inline: 'center',
        block: 'nearest'
      });
    }
  };

  useEffect(() => {
    if (highlightSeat) scrollToSeat(highlightSeat);
  }, [highlightSeat]);

  return (
    <div className="w-full space-y-8">
      {/* Coach Type Selector */}
      <div className="flex flex-wrap gap-2">
        {coachTypes.map((type) => (
          <button
            key={type}
            onClick={() => setCoachType(type)}
            className={clsx(
              "px-5 py-2.5 rounded-2xl text-sm font-black tracking-widest transition-all",
              coachType === type
                ? "bg-brand-blue text-main shadow-lg shadow-blue-500/40"
                : "bg-input text-muted border border-subtle hover:text-main hover:bg-card"
            )}
          >
            {type} Coach
          </button>
        ))}
      </div>

      {/* Search Berth */}
      <div className="relative max-w-xs">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-muted" size={18} />
        <input
          type="text"
          placeholder="Search berth number..."
          value={highlightSeat}
          onChange={(e) => setHighlightSeat(e.target.value)}
          className="w-full bg-input border border-subtle rounded-2xl py-3 pl-12 text-main placeholder:text-muted focus:border-brand-blue outline-none"
        />
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-6 text-xs">
        {[
          { label: 'Lower Berth', color: 'bg-blue-600 dark:bg-[#003366]' },
          { label: 'Middle/Upper', color: 'bg-blue-100 dark:bg-blue-400/20 border border-blue-300/40 dark:border-blue-400/40' },
          { label: 'Side Lower/Upper', color: 'bg-input border border-subtle' },
          { label: 'Window (CC)', color: 'bg-blue-600 dark:bg-[#003366]' },
          { label: 'Aisle (CC)', color: 'bg-emerald-500 dark:bg-emerald-600/80' },
        ].map((item, i) => (
          <div key={i} className="flex items-center gap-2">
            <div className={`w-4 h-4 rounded ${item.color}`} />
            <span className="text-muted font-medium">{item.label}</span>
          </div>
        ))}
      </div>

      {/* Seat Map */}
      <div className="relative">
        <div
          ref={scrollRef}
          className="flex gap-3 overflow-x-auto pb-8 px-2 snap-x snap-mandatory no-scrollbar"
        >
          {layout.map((seat) => (
            <div
              key={seat.number}
              ref={(el) => { seatRefs.current[seat.number] = el; }}
              onClick={() => {
                setHighlightSeat(seat.number.toString());
                onSeatSelect?.(seat);
              }}
              className={clsx(
                "min-w-[68px] h-20 flex flex-col items-center justify-center rounded-2xl border transition-all duration-300 cursor-pointer font-black text-lg shadow-md hover:scale-105",
                getSeatColor(seat.type, seat.number.toString() === highlightSeat)
              )}
            >
              <span className="relative z-10">{seat.number}</span>
              <span className="text-[9px] opacity-70 mt-0.5 tracking-tighter">{seat.type}</span>
            </div>
          ))}
        </div>

        {/* Scroll Hints */}
        <div className="absolute left-0 top-8 bottom-8 w-12 bg-gradient-to-r from-app to-transparent pointer-events-none" />
        <div className="absolute right-0 top-8 bottom-8 w-12 bg-gradient-to-l from-app to-transparent pointer-events-none" />
      </div>

      <div className="text-center text-[10px] text-muted font-black tracking-widest flex items-center justify-center gap-2">
        <ChevronLeft size={14} className="animate-pulse" />
        SCROLL TO EXPLORE FULL COACH
        <ChevronRight size={14} className="animate-pulse" />
      </div>
    </div>
  );
}